const roots = [
  { id: '1wAEiJ-X8Wi-b3rPe290gjeY3GqcbZTOH', name: 'Racine' },
];

return roots.map((root) => ({ json: root }));

const root = $('Résoudre drive racine').first().json ?? {};
const response = $input.first().json ?? {};
const entries = Array.isArray(response.files) ? response.files : [];
const FOLDER_MIME = 'application/vnd.google-apps.folder';

const childrenByParent = new Map();
for (const entry of entries) {
  const parents = Array.isArray(entry.parents) ? entry.parents : [];
  for (const parentId of parents) {
    if (!childrenByParent.has(parentId)) childrenByParent.set(parentId, []);
    childrenByParent.get(parentId).push(entry);
  }
}

const queue = [root.id];
const seenFolders = new Set([root.id]);
const recursiveFiles = [];

while (queue.length > 0) {
  const parentId = queue.shift();
  const children = childrenByParent.get(parentId) || [];

  for (const child of children) {
    if (child.mimeType === FOLDER_MIME) {
      if (!seenFolders.has(child.id)) {
        seenFolders.add(child.id);
        queue.push(child.id);
      }
      continue;
    }

    recursiveFiles.push(child);
  }
}

return recursiveFiles.map((file) => ({ json: file }));

const CHUNK_SIZE = 800;
const OVERLAP = 100;
const BINARY_EXTENSIONS = new Set(['pdf', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'zip', 'png', 'jpg', 'jpeg', 'gif', 'webp']);
const BINARY_MIME_PREFIXES = ['image/', 'audio/', 'video/'];
const BINARY_MIME_EXACT = new Set([
  'application/pdf',
  'application/zip',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  'application/msword',
  'application/vnd.ms-excel',
  'application/vnd.ms-powerpoint'
]);
const allChunks = [];

for (const item of $input.all()) {
  const file = item.json ?? {};
  const bin = item.binary?.data;

  if (!bin?.data) continue;

  const ext = String(bin.fileExtension || file.fileExtension || '').toLowerCase();
  const mime = String(bin.mimeType || file.mimeType || '').toLowerCase();
  const isClearlyBinary = BINARY_EXTENSIONS.has(ext)
    || BINARY_MIME_PREFIXES.some((prefix) => mime.startsWith(prefix))
    || BINARY_MIME_EXACT.has(mime);

  if (isClearlyBinary) continue;

  let texte = Buffer.from(bin.data, 'base64')
    .toString('utf8')
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (texte.length < 50) continue;

  let pos = 0;
  let ci = 0;

  while (pos < texte.length) {
    const chunk = texte
      .slice(pos, Math.min(pos + CHUNK_SIZE, texte.length))
      .trim();

    if (chunk.length > 50) {
      allChunks.push({
        json: {
          chunk_text: chunk,
          chunk_index: ci++,
          source_file: file.name || bin.fileName || 'Inconnu',
          source_id: file.id || null,
          source_url: file.webViewLink || null,
          modified_at: file.modifiedTime || new Date().toISOString(),
          source_ext: ext || null,
          source_mime: mime || null,
        },
      });
    }

    pos += CHUNK_SIZE - OVERLAP;
  }
}

return allChunks;

const embed = $json.data?.[0]?.embedding;
const meta = $('Découper en chunks').item.json ?? {};

if (!Array.isArray(embed) || embed.length === 0) {
  return [];
}

return [{
  json: {
    titre: meta.source_file || 'Inconnu',
    contenu: meta.chunk_text || '',
    url: meta.source_url || null,
    source_id: meta.source_id || null,
    chunk_index: meta.chunk_index ?? 0,
    modified_at: meta.modified_at || new Date().toISOString(),
    source_ext: meta.source_ext || null,
    source_mime: meta.source_mime || null,
    embedding: embed,
  },
}];

const results = $input.all();
const total = results.length;
const okItems = results.filter((item) => {
  const status = Number(item.json?.statusCode ?? 0);
  return status >= 200 && status < 300;
});
const failedItems = results.filter((item) => {
  const status = Number(item.json?.statusCode ?? 0);
  return !(status >= 200 && status < 300);
});
const driveList = $('Lister tous les éléments du drive').first().json ?? {};
const truncated = Boolean(driveList.nextPageToken);

const ok = okItems.length;
const failed = failedItems.length;
const errors = failedItems.slice(0, 5).map((item) => ({
  statusCode: item.json?.statusCode ?? null,
  body: item.json?.body ?? item.json ?? null,
}));

let message = failed === 0
  ? ok + '/' + total + ' chunks indexes dans Supabase.'
  : ok + '/' + total + ' chunks indexes dans Supabase, ' + failed + ' erreurs.';

if (truncated) {
  message += ' Attention: la liste Drive depasse 1000 elements, la pagination doit etre ajoutee.';
}

return [{
  json: {
    ok,
    total,
    failed,
    truncated,
    timestamp: new Date().toISOString(),
    message,
    errors,
  },
}];
